// Region data (country -> language, time zone, coordinates): content invariants, lookups, generator rules and determinism.
// apps/production-extension/fingerprint-region-data.js is generated by scripts/production/gen-region-data.mjs from the pinned tz
// database snapshot (packages/catalog/data/tzdata) and the ICU/CLDR of the Node that runs the generator. Counts below describe
// tzdata 2026f / ICU 77.1 and are updated together with a regeneration.
import test from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as region from '../../apps/production-extension/fingerprint-region-data.js';
import { canonicalTimeZone } from '../../apps/production-extension/fingerprint-timezone-data.js';
import * as gen from '../production/gen-region-data.mjs';

const root = new URL('../../', import.meta.url);
const read = (path) => readFileSync(new URL(path, root), 'utf8');
const sha256 = (text) => createHash('sha256').update(text, 'utf8').digest('hex');
const MODULE_PATH = 'apps/production-extension/fingerprint-region-data.js';
const MODULE_SOURCE = read(MODULE_PATH);
const GENERATOR = fileURLToPath(new URL('scripts/production/gen-region-data.mjs', root));
const TZDATA = 'packages/catalog/data/tzdata/';
const TAB_ROWS = read(TZDATA + 'zone.tab').split('\n').filter((line) => line !== '' && line[0] !== '#').map((line) => line.split('\t'));

const CODES = region.regionCodes();
const REGIONS = CODES.map((code) => region.regionByCode(code));
const ZONES = REGIONS.flatMap((entry) => entry.zones.map((zone) => ({ code: entry.code, ...zone })));
const viaIntl = (id) => new Intl.DateTimeFormat('en', { timeZone: id }).resolvedOptions().timeZone;

const recorded = /^\/\/ Toolchain: icu=(\S+) cldr=(\S+) unicode=(\S+) tz=(\S+)$/m.exec(MODULE_SOURCE);
const NOW = gen.toolchain();
const SAME_TOOLCHAIN = recorded !== null && recorded[1] === NOW.icu && recorded[2] === NOW.cldr && recorded[3] === NOW.unicode && recorded[4] === NOW.tz;
// Tests that run the generator over the real snapshot need the toolchain the module was generated with; elsewhere they skip.
const TOOLCHAIN_NOTE = 'this Node has ICU ' + NOW.icu + ' / CLDR ' + NOW.cldr + ' / Unicode ' + NOW.unicode + ' / tz ' + NOW.tz + '; the module was generated with ' +
  (recorded === null ? 'an unknown toolchain' : 'ICU ' + recorded[1] + ' / CLDR ' + recorded[2] + ' / Unicode ' + recorded[3] + ' / tz ' + recorded[4]);

function run(args) {
  return spawnSync(process.execPath, [GENERATOR, ...args], { encoding: 'utf8', timeout: 120000 });
}
function withTemp(callback) {
  const dir = mkdtempSync(join(tmpdir(), 'region-data-'));
  try {
    return callback(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}
function copyInputs(dir, transform = (text) => text) {
  mkdirSync(dir, { recursive: true });
  for (const name of gen.INPUT_FILES) writeFileSync(join(dir, name), transform(read(TZDATA + name), name));
}

// ---- the module ----------------------------------------------------------------------------------------------------------

test('exports exactly the documented API', () => {
  assert.deepEqual(Object.keys(region).sort(), ['REGION_DATA_VERSION', 'regionByCode', 'regionCodes', 'regionDefaults', 'regionOfTimeZone']);
  assert.ok(Number.isSafeInteger(region.REGION_DATA_VERSION) && region.REGION_DATA_VERSION >= 1);
  for (const name of ['regionByCode', 'regionCodes', 'regionDefaults', 'regionOfTimeZone']) assert.equal(typeof region[name], 'function', name);
  assert.match(MODULE_SOURCE, new RegExp('^export const REGION_DATA_VERSION = ' + region.REGION_DATA_VERSION + ';$', 'm'));
});

test('codes: two uppercase letters, strictly sorted, one region per country that has a zone in zone.tab', () => {
  assert.ok(Array.isArray(CODES) && CODES.length > 0);
  for (const code of CODES) assert.match(code, /^[A-Z]{2}$/);
  for (let index = 1; index < CODES.length; index++) assert.ok(CODES[index - 1] < CODES[index], CODES[index - 1] + ' < ' + CODES[index]);
  assert.deepEqual(CODES, [...new Set(TAB_ROWS.map((row) => row[0]))].sort());
  const iso = new Set(read(TZDATA + 'iso3166.tab').split('\n').filter((line) => line !== '' && line[0] !== '#').map((line) => line.split('\t')[0]));
  assert.ok(CODES.every((code) => iso.has(code)));
  assert.deepEqual([...iso].filter((code) => !CODES.includes(code)).sort(), ['BV', 'HM'], 'only the two countries without any zone are absent');
  region.regionCodes().push('ZZ');
  assert.deepEqual(region.regionCodes(), CODES, 'a fresh array on every call');
});

test('snapshot: 247 regions, 418 zones, 31 regions with several zones (tzdata 2026f)', () => {
  assert.equal(CODES.length, 247);
  assert.equal(ZONES.length, 418);
  assert.equal(REGIONS.filter((entry) => entry.zones.length > 1).length, 31);
});

test('every zone id is accepted by Intl in exactly the spelling Chrome reports (ICU canonical)', (t) => {
  for (const { iana } of ZONES) assert.doesNotThrow(() => new Intl.DateTimeFormat('en', { timeZone: iana }), iana);
  if (!SAME_TOOLCHAIN) {
    t.diagnostic('spelling checks skipped: this Node has another ICU than the module was generated with');
    return;
  }
  for (const { iana } of ZONES) {
    assert.equal(viaIntl(iana), iana, iana + ' is already canonical');
    assert.equal(canonicalTimeZone(iana), iana, iana + ' is stable under canonicalTimeZone');
  }
  // Measured on Chrome 156 (see fingerprint-timezone-canonical.test.mjs): the IANA primary name is stored as the ICU spelling.
  for (const [spelled, chrome] of [['Asia/Kolkata', 'Asia/Calcutta'], ['Europe/Kyiv', 'Europe/Kiev'], ['America/Argentina/Buenos_Aires', 'America/Buenos_Aires'],
    ['Asia/Kathmandu', 'Asia/Katmandu'], ['Asia/Yangon', 'Asia/Rangoon'], ['Asia/Ho_Chi_Minh', 'Asia/Saigon']]) {
    assert.equal(viaIntl(spelled), chrome, spelled + ' is reported as ' + chrome);
    assert.ok(ZONES.some((zone) => zone.iana === chrome), chrome + ' is stored');
    assert.ok(!ZONES.some((zone) => zone.iana === spelled), spelled + ' is not stored');
  }
});

test('zone entries: documented shape, ascii city, coordinates with at most 6 decimals, every id once in the whole table', () => {
  const seen = new Set();
  for (const { code, ...zone } of ZONES) {
    assert.deepEqual(Object.keys(zone), ['iana', 'city', 'lat', 'lon']);
    assert.match(zone.city, /^[\x21-\x7e](?:[\x20-\x7e]{0,38}[\x21-\x7e])?$/, zone.iana + ' city');
    for (const [name, limit] of [['lat', 90], ['lon', 180]]) {
      const value = zone[name];
      assert.ok(typeof value === 'number' && Number.isFinite(value) && Math.abs(value) <= limit, zone.iana + ' ' + name);
      assert.equal(Number(value.toFixed(6)), value, zone.iana + ' ' + name + ' has at most 6 decimals');
      assert.ok(!Object.is(value, -0));
    }
    assert.ok(!seen.has(zone.iana), zone.iana + ' appears once');
    seen.add(zone.iana);
  }
  if (SAME_TOOLCHAIN) {
    const supported = new Set(Intl.supportedValuesOf('timeZone'));
    assert.ok(ZONES.every((zone) => supported.has(zone.iana)), 'every zone is one of Intl.supportedValuesOf');
  }
});

test('coordinates equal an independent re-derivation from the ISO 6709 column of zone.tab', () => {
  const part = (sign, deg, min, sec) => (sign === '-' ? -1 : 1) * (Number(deg) + Number(min) / 60 + Number(sec ?? 0) / 3600);
  const byId = new Map(ZONES.map((zone) => [zone.iana, zone]));
  assert.equal(TAB_ROWS.length, ZONES.length);
  for (const [code, text, id] of TAB_ROWS) {
    const m = /^([+-])(\d\d)(\d\d)(\d\d)?([+-])(\d\d\d)(\d\d)(\d\d)?$/.exec(text);
    assert.ok(m, text);
    const zone = byId.get(viaIntl(id));
    assert.ok(zone, id);
    assert.equal(zone.code ?? region.regionOfTimeZone(id), code, id + ' belongs to ' + code);
    assert.ok(Math.abs(zone.lat - part(m[1], m[2], m[3], m[4])) < 6e-7, id + ' lat');
    assert.ok(Math.abs(zone.lon - part(m[5], m[6], m[7], m[8])) < 6e-7, id + ' lon');
  }
});

test('languages: canonical Chrome-style lists led by the locale, base language second, English tail rule', () => {
  const also = gen.ALSO_LANGUAGES;
  for (const entry of REGIONS) {
    const { code, locale, languages } = entry;
    assert.ok(Array.isArray(languages) && languages.length >= 2 && languages.length <= 6, code);
    assert.equal(new Set(languages).size, languages.length, code + ' has no duplicates');
    for (const tag of [...languages, locale]) assert.deepEqual(Intl.getCanonicalLocales(tag), [tag], code + ' ' + tag);
    assert.equal(languages[0], locale, code);
    const base = locale.split('-')[0];
    assert.equal(languages[1], base, code);
    const extra = (also[code] ?? []).flatMap((tag) => [tag, tag.split('-')[0]]);
    if (base === 'en') assert.deepEqual(languages.slice(2), extra, code + ' English locales end with their extras only');
    else assert.deepEqual(languages.slice(2), ['en-US', 'en'], code + ' ends with en-US, en');
  }
});

test('locale policy: region subtag, UI language, ICU data, plausible exceptions only', () => {
  const foreign = REGIONS.filter((entry) => entry.locale.split('-').pop() !== entry.code).map((entry) => entry.code);
  assert.deepEqual(foreign, ['AQ', 'BT', 'FO', 'SJ', 'TF'], 'regions whose locale names another country');
  for (const { code, locale, nameEn } of REGIONS) {
    assert.match(locale, /^[a-z]{2,3}-[A-Z]{2}$/, code);
    assert.ok(gen.UI_LANGUAGES.has(locale.split('-')[0]), code + ' ' + locale + ' has a UI language');
    if (SAME_TOOLCHAIN) assert.ok(gen.isBackedLocale(locale), code + ' ' + locale + ' has ICU locale data');
    assert.ok(typeof nameEn === 'string' && nameEn.length >= 2 && nameEn.length <= 60 && nameEn === nameEn.trim(), code);
  }
  assert.equal(new Set(REGIONS.map((entry) => entry.nameEn)).size, REGIONS.length, 'English names are unique');
  for (const [code, tag] of Object.entries(gen.LOCALE_OVERRIDES)) {
    assert.equal(region.regionByCode(code).locale, tag, code);
    assert.deepEqual(Intl.getCanonicalLocales(tag), [tag], code);
  }
  for (const code of Object.keys(gen.ALSO_LANGUAGES)) assert.ok(CODES.includes(code));
});

test('defaultZone: one of the zones; the only zone of a single-zone region; curated for every multi-zone region', () => {
  for (const entry of REGIONS) {
    assert.ok(entry.zones.length >= 1, entry.code);
    assert.equal(typeof entry.defaultZone, 'string');
    assert.ok(entry.zones.some((zone) => zone.iana === entry.defaultZone), entry.code + ' ' + entry.defaultZone);
    if (entry.zones.length === 1) assert.equal(entry.defaultZone, entry.zones[0].iana);
  }
  const multi = REGIONS.filter((entry) => entry.zones.length > 1).map((entry) => entry.code);
  assert.deepEqual(Object.keys(gen.DEFAULT_ZONE).sort(), multi, 'every multi-zone region has a curated default and no other does');
  for (const [code, id] of Object.entries(gen.DEFAULT_ZONE)) assert.equal(region.regionByCode(code).defaultZone, canonicalTimeZone(id), code);
  for (const [code, id] of [['US', 'America/New_York'], ['CA', 'America/Toronto'], ['RU', 'Europe/Moscow'], ['BR', 'America/Sao_Paulo'],
    ['AU', 'Australia/Sydney'], ['MX', 'America/Mexico_City'], ['CN', 'Asia/Shanghai'], ['ID', 'Asia/Jakarta'], ['KZ', 'Asia/Almaty'],
    ['AR', 'America/Buenos_Aires'], ['CD', 'Africa/Kinshasa'], ['MN', 'Asia/Ulaanbaatar'], ['CL', 'America/Santiago'], ['EC', 'America/Guayaquil'],
    ['ES', 'Europe/Madrid'], ['PT', 'Europe/Lisbon'], ['UA', 'Europe/Kiev'], ['DE', 'Europe/Berlin'], ['NZ', 'Pacific/Auckland']]) {
    assert.equal(region.regionByCode(code).defaultZone, id, code);
  }
});

test('regionOfTimeZone: round trip of every stored zone, every zone.tab spelling, legacy aliases, any letter case', () => {
  for (const { code, iana } of ZONES) assert.equal(region.regionOfTimeZone(iana), code, iana);
  for (const [code, , id] of TAB_ROWS) assert.equal(region.regionOfTimeZone(id), code, id + ' (spelled as in zone.tab)');
  for (const code of CODES) assert.equal(region.regionOfTimeZone(region.regionDefaults(code).timeZone), code);
  const aliases = [['Asia/Kolkata', 'IN'], ['Asia/Calcutta', 'IN'], ['Europe/Kyiv', 'UA'], ['Europe/Kiev', 'UA'], ['Asia/Ho_Chi_Minh', 'VN'], ['Asia/Saigon', 'VN'],
    ['US/Eastern', 'US'], ['US/Pacific', 'US'], ['Europe/Belfast', 'GB'], ['Asia/Istanbul', 'TR'], ['Asia/Katmandu', 'NP'], ['Asia/Rangoon', 'MM'],
    ['America/Argentina/Buenos_Aires', 'AR'], ['America/Buenos_Aires', 'AR'], ['Europe/Zurich', 'CH'], ['Europe/Busingen', 'DE'], ['europe/berlin', 'DE'],
    ['ASIA/KOLKATA', 'IN'], ['Asia/Thimbu', 'BT'], ['Canada/Eastern', 'CA'], ['Brazil/East', 'BR'], ['Australia/ACT', 'AU'], ['Asia/Chongqing', 'CN']];
  for (const [alias, code] of aliases) {
    if (canonicalTimeZone(alias) === alias && !ZONES.some((zone) => zone.iana === alias)) continue; // this runtime does not know the alias
    assert.equal(region.regionOfTimeZone(alias), code, alias);
  }
  assert.equal(region.regionOfTimeZone('Asia/Kolkata'), 'IN', 'the basic alias must work on this runtime');
  assert.equal(region.regionOfTimeZone('US/Eastern'), 'US', 'a plain alias must work on this runtime');
  // Names that are not Area/Location ids never imply a country, even though tzdata links some of them to a city zone.
  for (const name of ['EST', 'MST', 'HST', 'CET', 'MET', 'EET', 'WET', 'EST5EDT', 'PST8PDT', 'UTC', 'GMT', 'Zulu', 'Japan', 'PRC', 'ROK', 'GB', 'NZ', 'Turkey', 'Singapore', 'Cuba']) {
    assert.equal(region.regionOfTimeZone(name), null, name);
  }
  assert.equal(region.regionOfTimeZone('Europe/Berlin'), region.regionOfTimeZone('Europe/Berlin'), 'repeatable');
});

test('regionOfTimeZone also matches when the browser spells zones differently (Firefox-like Intl)', async () => {
  const Native = Intl.DateTimeFormat;
  const primary = { 'Asia/Calcutta': 'Asia/Kolkata', 'Europe/Kiev': 'Europe/Kyiv', 'America/Buenos_Aires': 'America/Argentina/Buenos_Aires' };
  class FirefoxLike extends Native {
    resolvedOptions() {
      const options = super.resolvedOptions();
      return { ...options, timeZone: primary[options.timeZone] ?? options.timeZone };
    }
  }
  Intl.DateTimeFormat = FirefoxLike;
  try {
    const fresh = await import(new URL(MODULE_PATH, root).href + '?firefox-like');
    assert.equal(canonicalTimeZone('Asia/Calcutta'), 'Asia/Kolkata', 'the stub is active');
    assert.equal(fresh.regionOfTimeZone('Asia/Calcutta'), 'IN', 'stored spelling');
    assert.equal(fresh.regionOfTimeZone('Asia/Kolkata'), 'IN', 'the browser spelling');
    assert.equal(fresh.regionOfTimeZone('Europe/Kyiv'), 'UA');
    assert.equal(fresh.regionOfTimeZone('America/Argentina/Buenos_Aires'), 'AR');
    assert.equal(fresh.regionOfTimeZone('Europe/Berlin'), 'DE');
    assert.equal(fresh.regionOfTimeZone('Not/AZone'), null);
    assert.equal(fresh.regionOfTimeZone('UTC'), null);
  } finally {
    Intl.DateTimeFormat = Native;
  }
  assert.equal(canonicalTimeZone('Asia/Kolkata'), viaIntl('Asia/Kolkata'), 'the real Intl is back');
});

test('unknown and hostile input gives null and is never coerced', () => {
  let coerced = 0;
  const trap = {
    toString() { coerced++; return 'DE'; },
    valueOf() { coerced++; return 'DE'; },
    [Symbol.toPrimitive]() { coerced++; return 'DE'; },
  };
  const notStrings = [undefined, null, 5, 5n, true, {}, [], ['DE'], ['Europe/Berlin'], Symbol('DE'), () => 'DE', trap, new String('DE'), new String('Europe/Berlin')];
  for (const value of notStrings) {
    assert.equal(region.regionByCode(value), null, 'regionByCode ' + typeof value);
    assert.equal(region.regionDefaults(value), null, 'regionDefaults ' + typeof value);
    assert.equal(region.regionOfTimeZone(value), null, 'regionOfTimeZone ' + typeof value);
  }
  assert.equal(coerced, 0, 'no coercion of an argument');
  for (const code of ['', 'D', 'DEU', 'D1', '1D', ' DE', 'DE ', 'D\u0000', 'ıd', 'ſe', 'KK', 'XX', 'ZZ', 'BV', 'HM', 'XK', 'D-', '__']) {
    assert.equal(region.regionByCode(code), null, JSON.stringify(code));
    assert.equal(region.regionDefaults(code), null, JSON.stringify(code));
  }
  for (const zone of ['', ' ', 'UTC', 'Etc/UTC', 'Etc/GMT+5', 'GMT', 'EST', 'Not/AZone', 'Europe/Nowhere', 'Europe/', '/Berlin', '+05:30', 'Z', 'Europe/Berlin\u0000',
    ' Europe/Berlin', 'Europe/Berlin ', 'x'.repeat(129), 'Europe/' + 'a'.repeat(200), '__proto__', 'constructor', 'hasOwnProperty']) {
    assert.equal(region.regionOfTimeZone(zone), null, JSON.stringify(zone).slice(0, 40));
  }
  assert.equal(region.regionByCode('de'), region.regionByCode('DE'));
  assert.equal(region.regionByCode('dE'), region.regionByCode('De'));
});

test('regionDefaults: documented shape, coordinates of the default zone, fresh copies; regions are frozen and shared', () => {
  const defaults = region.regionDefaults('de');
  assert.deepEqual(Object.keys(defaults), ['code', 'timeZone', 'locale', 'languages', 'latitude', 'longitude', 'accuracy']);
  assert.equal(defaults.accuracy, 25);
  for (const code of CODES) {
    const entry = region.regionByCode(code);
    const zone = entry.zones.find((candidate) => candidate.iana === entry.defaultZone);
    assert.deepEqual(region.regionDefaults(code), {
      code, timeZone: zone.iana, locale: entry.locale, languages: [...entry.languages], latitude: zone.lat, longitude: zone.lon, accuracy: 25,
    }, code);
  }
  defaults.languages.push('xx');
  defaults.timeZone = 'Mars/Base';
  const again = region.regionDefaults('DE');
  assert.notEqual(again, defaults);
  assert.deepEqual(again.languages, ['de-DE', 'de', 'en-US', 'en']);
  assert.equal(again.timeZone, 'Europe/Berlin');
  assert.ok(!Object.isFrozen(again) && !Object.isFrozen(again.languages), 'defaults are plain copies');

  const germany = region.regionByCode('DE');
  assert.equal(germany, region.regionByCode('de'));
  assert.ok(Object.isFrozen(germany) && Object.isFrozen(germany.languages) && Object.isFrozen(germany.zones) && germany.zones.every(Object.isFrozen));
  assert.throws(() => { germany.locale = 'x'; }, TypeError);
  assert.throws(() => { germany.languages.push('x'); }, TypeError);
  assert.throws(() => { germany.zones[0].lat = 0; }, TypeError);
  assert.deepEqual(Object.keys(germany), ['code', 'nameEn', 'locale', 'languages', 'zones', 'defaultZone']);
  assert.deepEqual(JSON.parse(JSON.stringify(germany)), { ...germany, languages: [...germany.languages], zones: germany.zones.map((zone) => ({ ...zone })) });
});

