test('fixed expectations for DE, CH, US, RU, AU, JP, BR, IN, GB, CA', () => {
  for (const want of EXPECTED) {
    for (const code of [want.code, want.code.toLowerCase()]) {
      const entry = region.regionByCode(code);
      assert.equal(entry.code, want.code);
      assert.equal(entry.nameEn, want.nameEn);
      assert.equal(entry.locale, want.locale);
      assert.deepEqual([...entry.languages], want.languages);
      assert.equal(entry.zones.length, want.zoneCount, want.code + ' zones');
      assert.equal(entry.defaultZone, want.defaultZone);
    }
    const zone = region.regionByCode(want.code).zones.find((candidate) => candidate.iana === want.defaultZone);
    assert.equal(zone.city, want.city);
    assert.deepEqual(region.regionDefaults(want.code), {
      code: want.code, timeZone: want.defaultZone, locale: want.locale, languages: want.languages, latitude: want.lat, longitude: want.lon, accuracy: 25,
    });
  }
  assert.deepEqual(region.regionByCode('DE').zones.map((zone) => zone.iana), ['Europe/Berlin', 'Europe/Busingen']);
  assert.deepEqual(region.regionByCode('DE').zones[1], { iana: 'Europe/Busingen', city: 'Busingen', lat: 47.7, lon: 8.683333 });
  assert.deepEqual(region.regionByCode('UM').zones.map((zone) => zone.city), ['Midway', 'Wake']);
  assert.equal(region.regionByCode('HK').nameEn, 'Hong Kong SAR China');
  assert.equal(region.regionByCode('CI').nameEn, 'Côte d’Ivoire');
  assert.equal(region.regionByCode('TW').locale, 'zh-TW');
  assert.equal(region.regionByCode('NO').locale, 'nb-NO');
  assert.equal(region.regionByCode('BY').locale, 'ru-BY');
});

test('coordinates of the default zone agree with well-known cities within 1.5 degrees', () => {
  const cities = [['DE', 52.52, 13.405], ['FR', 48.857, 2.352], ['GB', 51.507, -0.128], ['JP', 35.682, 139.692], ['US', 40.713, -74.006],
    ['RU', 55.756, 37.617], ['AU', -33.869, 151.209], ['BR', -23.55, -46.633], ['IN', 22.573, 88.364], ['CN', 31.23, 121.474],
    ['EG', 30.044, 31.236], ['ZA', -26.204, 28.047], ['AR', -34.604, -58.382], ['MX', 19.433, -99.133], ['TR', 41.008, 28.978],
    ['KR', 37.567, 126.978], ['CA', 43.651, -79.347], ['NZ', -36.848, 174.763], ['ES', 40.417, -3.704], ['IT', 41.903, 12.496],
    ['SA', 24.714, 46.675], ['NG', 6.524, 3.379], ['ID', -6.209, 106.846], ['CH', 47.377, 8.541], ['PL', 52.23, 21.012]];
  assert.ok(cities.length >= 15);
  for (const [code, lat, lon] of cities) {
    const { latitude, longitude } = region.regionDefaults(code);
    assert.ok(Math.abs(latitude - lat) <= 1.5, code + ' latitude ' + latitude + ' vs ' + lat);
    assert.ok(Math.abs(longitude - lon) <= 1.5, code + ' longitude ' + longitude + ' vs ' + lon);
  }
});

test('ICU agrees with the table: Locale#getTimeZones per region, supportedValuesOf as a whole (tzdata 2026f vs ICU 77.1)', (t) => {
  if (!SAME_TOOLCHAIN) {
    t.skip('this Node has another ICU than the module was generated with');
    return;
  }
  if (typeof new Intl.Locale('und-DE').getTimeZones !== 'function') {
    t.skip('Intl.Locale#getTimeZones is not available');
    return;
  }
  for (const entry of REGIONS) {
    const icu = new Intl.Locale('und-' + entry.code).getTimeZones();
    assert.deepEqual([...icu].sort(), entry.zones.map((zone) => zone.iana).sort(), entry.code);
  }
  assert.deepEqual([...Intl.supportedValuesOf('timeZone')].sort(), ZONES.map((zone) => zone.iana).sort());
});

