test('module file: small, ascii only, no URL or network call, sane line lengths, lint-friendly', () => {
  assert.ok(Buffer.byteLength(MODULE_SOURCE) < 60 * 1024, 'under 60 KiB: ' + Buffer.byteLength(MODULE_SOURCE));
  assert.ok(/^[\x09\x0a\x20-\x7e]*$/.test(MODULE_SOURCE), 'ascii only');
  assert.ok(!MODULE_SOURCE.includes('\r'));
  assert.ok(MODULE_SOURCE.endsWith('}\n'));
  for (const [index, line] of MODULE_SOURCE.split('\n').entries()) {
    assert.ok(line.length <= 200, 'line ' + (index + 1) + ' is ' + line.length + ' characters');
    assert.equal(line, line.trimEnd(), 'trailing space on line ' + (index + 1));
  }
  const noNetwork = /\bfetch\s*\(|XMLHttpRequest|WebSocket|EventSource|sendBeacon|importScripts|\beval\s*\(|\bnew\s+Function\b|https?:\/\/|storage\.sync/;
  assert.ok(!noNetwork.test(MODULE_SOURCE), 'no network or dynamic code in the module');
  assert.ok(!noNetwork.test(readFileSync(GENERATOR, 'utf8')), 'no network or URL in the generator');
  assert.deepEqual([...MODULE_SOURCE.matchAll(/^import .* from '([^']+)';$/gm)].map((match) => match[1]), ['./fingerprint-timezone-data.js']);
  assert.equal(MODULE_SOURCE.match(/\n\s*export /g).length + (MODULE_SOURCE.startsWith('export ') ? 1 : 0), 5);
});

test('provenance: header hashes equal the vendored tz files, the notice and SOURCE.md agree with the header', () => {
  const tz = read(TZDATA + 'version').trim();
  const header = MODULE_SOURCE.split('\n').filter((line) => line.startsWith('//')).join('\n');
  const source = read(TZDATA + 'SOURCE.md');
  const notice = read('apps/production-extension/REGION-DATA-NOTICE.txt');
  const bundledNotice = read('apps/production-extension/NOTICE');
  assert.match(tz, /^\d{4}[a-z]$/);
  assert.ok(header.includes('IANA tz database ' + tz + ' (public domain)'));
  for (const name of ['zone.tab', 'zone1970.tab', 'iso3166.tab']) {
    const hash = sha256(read(TZDATA + name).replace(/\r\n/g, '\n'));
    assert.match(header, new RegExp('^//\\s+' + name.replace('.', '\\.') + '\\s+' + hash + '$', 'm'), name + ' hash in the module header');
    assert.ok(notice.includes(hash), name + ' hash in REGION-DATA-NOTICE.txt');
    assert.ok(source.includes(hash), name + ' hash in SOURCE.md');
  }
  assert.ok(source.includes(sha256(read(TZDATA + 'version'))), 'version hash in SOURCE.md');
  assert.ok(source.includes('tzdb-' + tz) && source.includes('tzdata' + tz + '.tar.gz'));
  const [, icu, cldr, unicode, zoneData] = recorded;
  assert.match(header, new RegExp('Unicode CLDR ' + cldr.replace('.', '\\.') + ' through ICU ' + icu.replace('.', '\\.') + ' \\(Unicode ' + unicode.replace('.', '\\.') + ', ICU tz data ' + zoneData));
  for (const text of ['release ' + tz, 'CLDR ' + cldr + ' through ICU ' + icu, 'Unicode ' + unicode + ', ICU time zone data ' + zoneData, CODES.length + ' regions', ZONES.length + ' time zones']) {
    assert.ok(notice.includes(text), 'REGION-DATA-NOTICE.txt says "' + text + '"');
  }
  for (const text of ['REGION-DATA-NOTICE.txt', 'tz database ' + tz, 'CLDR ' + cldr + ' / ICU ' + icu, 'Unicode License v3']) {
    assert.ok(bundledNotice.includes(text), 'NOTICE says "' + text + '"');
  }
  // The license text is reproduced unchanged: the hash stated next to it is the hash of the text between the two rules.
  const rule = '-'.repeat(78);
  const parts = notice.split(rule + '\n');
  assert.equal(parts.length, 3, 'the license sits between two rules');
  const license = parts[1].replace(/\n$/, '');
  assert.ok(license.startsWith('UNICODE LICENSE V3\n\nCOPYRIGHT AND PERMISSION NOTICE\n\nCopyright © 1991-'));
  assert.ok(license.includes('Permission is hereby granted, free of charge') && license.endsWith('authorization of the copyright holder.'));
  assert.equal(notice.match(/retrieved \d{4}-\d\d-\d\d, sha256 ([0-9a-f]{64})/)[1], sha256(license + '\n'));
});

