const ISO = new Map([['DE', 'Germany'], ['IN', 'India'], ['BV', 'Bouvet Island'], ['GH', 'Ghana'], ['FR', 'France']]);
const TABLES = { defaultZone: { DE: 'Europe/Berlin' }, localeOverrides: {}, alsoLanguages: {} };
const NO_TABLES = { defaultZone: {}, localeOverrides: {}, alsoLanguages: {} };
const rowsOf = (...lines) => gen.parseZoneTab(lines.join('\n') + '\n');

test('buildRegions: drops ids Intl rejects, respells, sorts, picks defaults and reports it all', () => {
  const zoneRows = rowsOf('IN\t+2232+08822\tAsia/Kolkata', 'DE\t+4742+00841\tEurope/Busingen\tBusingen', 'DE\t+5230+01322\tEurope/Berlin\tmost of Germany',
    'DE\t+5230+01322\tNot/AZone\tbogus', 'BV\t-5425+00333\tNot/AZoneToo');
  const { regions, report } = gen.buildRegions({ zoneRows, isoNames: ISO, tables: TABLES });
  assert.deepEqual(regions.map((entry) => entry.code), ['DE', 'IN']);
  assert.deepEqual(regions[0].zones, [{ iana: 'Europe/Busingen', city: 'Busingen', lat: 47.7, lon: 8.683333 }, { iana: 'Europe/Berlin', city: 'Berlin', lat: 52.5, lon: 13.366667 }]);
  assert.equal(regions[0].defaultZone, 'Europe/Berlin');
  assert.equal(regions[0].locale, 'de-DE');
  assert.deepEqual(regions[0].languages, ['de-DE', 'de', 'en-US', 'en']);
  assert.equal(regions[0].nameEn, 'Germany');
  assert.deepEqual(regions[1], { code: 'IN', nameEn: 'India', locale: 'hi-IN', languages: ['hi-IN', 'hi', 'en-US', 'en'], defaultZone: 'Asia/Calcutta',
    zones: [{ iana: 'Asia/Calcutta', city: 'Kolkata', lat: 22.533333, lon: 88.366667 }] });
  assert.deepEqual(report.rejected, ['Not/AZone', 'Not/AZoneToo']);
  assert.deepEqual(report.droppedRegions, ['BV']);
  assert.deepEqual(report.respelled, ['Asia/Kolkata -> Asia/Calcutta']);
  assert.deepEqual(report.defaultFallback, []);
  assert.deepEqual(report.icu, [], 'ICU lists exactly these zones for DE and IN');
});

test('buildRegions: default zone fallback rule, duplicates after canonicalisation, English names, extra languages', () => {
  const noComments = rowsOf('DE\t+4742+00841\tEurope/Busingen', 'DE\t+5230+01322\tEurope/Berlin');
  let built = gen.buildRegions({ zoneRows: noComments, isoNames: ISO, tables: { ...TABLES, defaultZone: {} } });
  assert.equal(built.regions[0].defaultZone, 'Europe/Busingen', 'no comment: the first zone');
  assert.deepEqual(built.report.defaultFallback, ['DE']);
  const commented = rowsOf('DE\t+4742+00841\tEurope/Busingen\tBusingen', 'DE\t+5230+01322\tEurope/Berlin\tmost of Germany');
  built = gen.buildRegions({ zoneRows: commented, isoNames: ISO, tables: { ...TABLES, defaultZone: {} } });
  assert.equal(built.regions[0].defaultZone, 'Europe/Berlin', '"most of" comment wins');
  built = gen.buildRegions({ zoneRows: rowsOf('IN\t+2232+08822\tAsia/Kolkata', 'IN\t+2232+08822\tAsia/Calcutta'), isoNames: ISO, tables: NO_TABLES });
  assert.equal(built.regions[0].zones.length, 1);
  assert.equal(built.report.duplicates.length, 1);
  built = gen.buildRegions({ zoneRows: rowsOf('IN\t+2232+08822\tAsia/Kolkata'), isoNames: ISO,
    tables: { ...NO_TABLES, localeOverrides: { IN: 'en-IN' }, alsoLanguages: { IN: ['hi-IN'] } } });
  assert.deepEqual(built.regions[0].languages, ['en-IN', 'en', 'hi-IN', 'hi']);
  assert.deepEqual(built.report.localeOverrides, ['IN: hi-IN -> en-IN']);
  assert.deepEqual(gen.buildRegions({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin'), isoNames: new Map([['DE', 'Federal Republic']]), tables: NO_TABLES })
    .regions[0].nameEn, 'Germany', 'Intl.DisplayNames wins over the tab name');
  assert.deepEqual(gen.buildRegions({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin'), isoNames: ISO, tables: TABLES })
    .report.warnings.length, 1, 'a curated default for a single-zone region is flagged');
  assert.deepEqual(gen.buildRegions({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin'), isoNames: ISO, tables: { ...NO_TABLES, localeOverrides: { DE: 'de-DE' } } })
    .report.warnings, ['LOCALE_OVERRIDES.DE repeats the CLDR locale de-DE'], 'a redundant locale override is flagged');
  // ICU cross-check: a region that lacks a zone ICU lists, and a zone that is not a canonical location, are reported (not fatal).
  const icu = gen.buildRegions({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin', 'DE\t+0000+00000\tEtc/GMT+5'), isoNames: ISO, tables: NO_TABLES }).report.icu;
  assert.equal(icu.length, 2);
  assert.match(icu[0], /^DE: ICU .*Europe\/Busingen.* \/ table Europe\/Berlin,Etc\/GMT\+5$/);
  assert.equal(icu[1], 'DE: Etc/GMT+5 is not in Intl.supportedValuesOf');
});

test('buildRegions: refuses silently wrong data', () => {
  const berlin = rowsOf('DE\t+5230+01322\tEurope/Berlin');
  const fail = (input, message) => assert.throws(() => gen.buildRegions({ isoNames: ISO, tables: NO_TABLES, ...input }), message);
  fail({ zoneRows: berlin, isoNames: new Map([['IN', 'India']]) }, /missing from iso3166\.tab/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, defaultZone: { FR: 'Europe/Paris' } } }, /unknown region FR/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, localeOverrides: { FR: 'fr-FR' } } }, /unknown region FR/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, alsoLanguages: { FR: ['fr-CA'] } } }, /unknown region FR/);
  fail({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin', 'DE\t+4742+00841\tEurope/Busingen'), tables: { ...NO_TABLES, defaultZone: { DE: 'Europe/Paris' } } }, /not a zone of the region/);
  fail({ zoneRows: rowsOf('GH\t+0533-00013\tAfrica/Accra') }, /GH: CLDR likely locale .* needs a LOCALE_OVERRIDES entry/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, localeOverrides: { DE: 'DE-de' } } }, /not a canonical language tag/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, localeOverrides: { DE: 'en-BT' } } }, /no locale data/);
  fail({ zoneRows: berlin, tables: { ...NO_TABLES, alsoLanguages: { DE: ['en-BT'] } } }, /no locale data/);
  fail({ zoneRows: rowsOf('DE\t+5230+01322\tEurope/Berlin', 'FR\t+4852+00220\tEurope/Berlin') }, /belongs to DE and FR/);
  fail({ zoneRows: berlin, zone1970: [{ codes: ['DE'], tz: 'Europe/Paris' }] }, /zone1970\.tab zone Europe\/Paris is missing/);
  fail({ zoneRows: berlin, zone1970: [{ codes: ['FR'], tz: 'Europe/Berlin' }] }, /zone1970\.tab country FR is missing/);
  fail({ zoneRows: rowsOf('BV\t-5425+00333\tNot/AZone') }, /no regions built/);
  assert.equal(gen.buildRegions({ isoNames: ISO, tables: NO_TABLES, zoneRows: berlin, zone1970: [{ codes: ['DE'], tz: 'Europe/Berlin' }] }).regions.length, 1);
});

