test('CLI --check: hand edits and stale files fail with a line number, another toolchain gives exit 3, a missing file fails', (t) => {
  if (!SAME_TOOLCHAIN) {
    t.skip(TOOLCHAIN_NOTE);
    return;
  }
  withTemp((dir) => {
    const target = join(dir, 'module.js');
    assert.equal(run(['--output', target]).status, 0);
    const fresh = readFileSync(target, 'utf8');
    const ok = run(['--check', '--output', target]);
    assert.equal(ok.status, 0, ok.stderr);

    const edited = fresh.replace("'Europe/Berlin', 'Berlin', 52.5,", "'Europe/Berlin', 'Berlin', 52.6,");
    assert.notEqual(edited, fresh);
    writeFileSync(target, edited);
    const stale = run(['--check', '--output', target]);
    assert.equal(stale.status, 1);
    assert.match(stale.stderr, /stale or was edited by hand; first difference at line \d+/);
    assert.match(stale.stderr, /52\.5/);

    writeFileSync(target, fresh.replace(/^\/\/ Toolchain: icu=\S+/m, '// Toolchain: icu=1.0'));
    const other = run(['--check', '--output', target]);
    assert.equal(other.status, 3);
    assert.match(other.stderr, /cannot verify/);

    writeFileSync(target, fresh.replace(/^\/\/ Toolchain:.*$/m, '// no toolchain line'));
    assert.equal(run(['--check', '--output', target]).status, 3, 'a header without the toolchain line cannot be verified');

    writeFileSync(target, fresh + '// trailing edit\n');
    assert.equal(run(['--check', '--output', target]).status, 1);

    const missing = run(['--check', '--output', join(dir, 'nope.js')]);
    assert.equal(missing.status, 1);
    assert.match(missing.stderr, /is missing/);
  });
});

test('CLI: changed inputs add one to the version and reach the output; bad arguments and bad inputs fail loudly', () => {
  if (SAME_TOOLCHAIN) withTemp((dir) => {
    const input = join(dir, 'tzdata');
    copyInputs(input, (text, name) => (name === 'zone.tab' ? text.replace('AD\t+4230+00131', 'AD\t+4231+00131') : text));
    const out = join(dir, 'changed.js');
    const changed = run(['--input-dir', input, '--output', out]);
    assert.equal(changed.status, 0, changed.stderr);
    const text = readFileSync(out, 'utf8');
    assert.match(text, /\['Europe\/Andorra', 'Andorra', 42\.516667, 1\.516667\]/);
    assert.match(text, new RegExp('^export const REGION_DATA_VERSION = ' + (region.REGION_DATA_VERSION + 1) + ';$', 'm'));
    assert.notEqual(text.match(/zone\.tab\s+(\w{64})/)[1], MODULE_SOURCE.match(/zone\.tab\s+(\w{64})/)[1], 'the header records the new hash');
  });
  const bad = (args, message) => {
    const result = run(args);
    assert.equal(result.status, 1, args.join(' '));
    assert.match(result.stderr, message, args.join(' '));
  };
  bad(['--bogus'], /unknown argument/);
  bad(['--input-dir'], /needs a value/);
  bad(['--output', '--check'], /needs a value/);
  bad(['--input-dir', join(tmpdir(), 'region-data-does-not-exist')], /missing input file/);
  withTemp((dir) => {
    copyInputs(dir, (text, name) => (name === 'zone.tab' ? text + 'XX\t+0000+00000\tEurope/Berlin\n' : text));
    bad(['--input-dir', dir, '--output', join(dir, 'x.js')], /belongs to|missing from iso3166|CLDR likely|no locale/);
    copyInputs(dir, (text, name) => (name === 'zone.tab' ? text.replace('AD\t+4230+00131', 'AD\t+4230') : text));
    bad(['--input-dir', dir, '--output', join(dir, 'x.js')], /bad ISO 6709 coordinates: \+4230/);
    copyInputs(dir, (text, name) => (name === 'zone.tab' ? text.replace('AD\t+4230+00131\tEurope/Andorra', 'AD\tEurope/Andorra') : text));
    bad(['--input-dir', dir, '--output', join(dir, 'x.js')], /zone\.tab line \d+: expected 3 or 4/);
  });
});
